# Ranked Result Delivery demo: declared criteria, multi-signal scoring, explanations.
DOCS=[{"id":"d1","text":"solar sail propulsion photon pressure","fresh":2,"auth":0.9},
      {"id":"d2","text":"solar panels sail boats","fresh":90,"auth":0.5},
      {"id":"d3","text":"photon propulsion sails for deep space probes","fresh":10,"auth":0.8}]
W={"rel":0.6,"fresh":0.2,"auth":0.2}
def rel(q,d):
    qt=set(q.split()); dt=d["text"].split()
    return sum(dt.count(t) for t in qt)/max(1,len(dt))
def score(q,d):
    r=rel(q,d); f=1.0/(1+d["fresh"]/30.0); a=d["auth"]
    s=W["rel"]*r+W["fresh"]*f+W["auth"]*a
    return s,{"relevance":round(r,3),"freshness":round(f,3),"authority":a}
q="solar sail propulsion"
for d in sorted(DOCS,key=lambda d:-score(q,d)[0]):
    s,exp=score(q,d); print(d["id"],round(s,3),exp)
print("criteria weights:",W)

